module x_oracle::oracle_admin;

use pyth::price_info::PriceInfoObject;
use sui::clock::Clock;
use sui::event::emit;

use x_oracle::pyth_adaptor;

public struct PriceDelayToleranceUpdated has drop, copy {
    oracle: ID,
    delay_ms: u64,
    who: address,
    timestamp: u64,
}

public fun migrate(_: &x_oracle::x_oracle::AdminCap, x_oracle: &mut x_oracle::x_oracle::XOracle): u64 {
    x_oracle.migrate()
}

public fun register_pyth_feed<CoinType>(
    _: &x_oracle::x_oracle::AdminCap,
    x_oracle: &mut x_oracle::x_oracle::XOracle,
    pyth_info_object: &PriceInfoObject,
    spot_confidence_tolerance_bps: u64,  // per 10,000. so 1 = 0.01%
    ema_confidence_tolerance_bps: u64,  // per 10,000. so 1 = 0.01%
) {
    pyth_adaptor::register_pyth_feed<CoinType>(
        x_oracle.pyth_price_feeds_mut(),
        pyth_info_object,
        spot_confidence_tolerance_bps,
        ema_confidence_tolerance_bps,
    );
}

public fun update_price_delay_tolerance_ms(
    _: &x_oracle::x_oracle::AdminCap,
    x_oracle: &mut x_oracle::x_oracle::XOracle,
    delay_tolerance_ms: u64,
    clock: &Clock,
    ctx: &TxContext,
) {
    x_oracle.update_price_delay_tolerance_ms(delay_tolerance_ms);

    emit(PriceDelayToleranceUpdated {
        oracle: object::id(x_oracle),
        delay_ms: delay_tolerance_ms,
        who: ctx.sender(),
        timestamp: clock.timestamp_ms() / 1000,
    });
}

/// @title A module dedicated for handling the borrow request from user
module protocol::borrow;

use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::{Self, Coin};
use sui::event::emit;

use math::float::Decimal;

use x_oracle::x_oracle::XOracle;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_borrow_reward_type;
use protocol::app::ProtocolApp;

public struct BorrowEvent has copy, drop {
    borrower: address,

    market: TypeName,
    obligation: ID,

    asset: TypeName,

    amount: u64,
    total_borrow: Decimal,
    borrow_index: Decimal,

    time: u64,
}

public fun borrow<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    borrow_amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock::timestamp_ms(clock) / 1000;

    let (borrowed_balance, borrow_index, total_borrow) = market.handle_borrow(
        obligation_owner_cap.id(),
        borrow_amount,
        coin_decimals_registry,
        x_oracle,
        clock,
        now
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_borrow_reward_type(),
        obligation_owner_cap.id(),
        total_borrow.floor(),
        clock
    );

    // Emit the borrow event
    emit(BorrowEvent {
        borrower: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        asset: type_name::with_defining_ids<CoinType>(),
        amount: borrow_amount,

        total_borrow,
        borrow_index,

        time: now,
    });

    coin::from_balance(borrowed_balance, ctx)
}

