// calculate the actual repay amount, actual liquidate amount, actual market amount
fun liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
    exchange_rate: Decimal,
    liquidation_incentive: Decimal,
    actual_repay_amount: u64,

    oracle_base_token: x_oracle::x_oracle::BaseToken,
    x_oracle: &XOracle,

    coin_registry: &CoinDecimalsRegistry,
    clock: &Clock,
): u64 {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let price_borrowed = get_spot_price(x_oracle, debt_type, oracle_base_token, clock);
    let price_collateral = get_spot_price(x_oracle, collateral_type, oracle_base_token, clock);

    let actual_repay_amount = float::from(actual_repay_amount);

    let debt_decimals = math::u64::pow10_u64(coin_registry.decimals(debt_type));
    let collateral_decimals = math::u64::pow10_u64(coin_registry.decimals(collateral_type));

    /*
     * Get the exchange rate and calculate the number of collateral tokens to seize:
     *  seizeAmount = (actualRepayAmount + actualRepayAmount * liquidationIncentive) * priceBorrowed / priceCollateral
     *  seizeTokens = seizeAmount / exchangeRate
     */
    let incentivised_borrow = actual_repay_amount.add(actual_repay_amount.mul(
        liquidation_incentive,
    ));
    // ignoreing decimal calculation as they will be cancelled out
    let incentivised_borrow_usd = incentivised_borrow.mul(price_borrowed).div_u64(debt_decimals);
    let seize_collaterals = incentivised_borrow_usd.div(price_collateral).mul_u64(collateral_decimals);

    let seize_ctokens = seize_collaterals.div(exchange_rate);

    assert!(
        seize_ctokens.lt(float::from(std::u64::max_value!())),
        error::invariant_seize_tokens_crazy_big(),
    );

    // only take the tecnnically possible amount
    seize_ctokens.floor()
}

